    if l.strip(): print(f,i,l.rstrip()[:200])
for f in sorted(glob.glob('/task/fixtures/round-05/logs/*.log')):
  c=Counter();n=0
  for i,l in enumerate(open(f),1):
    if 'INFO' in l or 'slow query' in l: continue
